        "type": "object",
        "description": "待办事项",
        "properties": {
          "text": {
            "type": "string",
            "description": "待办内容",
            "example": "完成原型设计"
          },
          "assignee": {
            "type": "string",
            "description": "责任人（如提及）",
            "example": "张三"
          },
          "dueDate": {
            "type": "integer",
            "format": "int64",
            "description": "截止日期（毫秒时间戳）",
